<script setup lang="ts">
import { computed, ref } from 'vue'
import type { Editor } from '../lib/editor'
import { newId, type BackendConfig, type WindowTemplate } from '../lib/model'
import { call, desktop, pickFile } from '../lib/backend'
import { schemaDefaults } from '../lib/schema'
import { t } from '../lib/i18n'
import JsonValueEditor from './JsonValueEditor.vue'
const props=defineProps<{editor:Editor;mode:'backends'|'windows'}>()
const emit=defineEmits<{error:[message:string]}>()
const selected=ref(''),importing=ref(false)
const backends=computed(()=>props.editor.project.value.backends??[]),windows=computed(()=>props.editor.project.value.windows??[])
const items=computed(()=>props.mode==='backends'?backends.value:windows.value)
const current=computed(()=>items.value.find(item=>item.id===selected.value)??items.value[0])
const backend=computed(()=>props.mode==='backends'?current.value as BackendConfig|undefined:undefined)
const windowTemplate=computed(()=>props.mode==='windows'?current.value as WindowTemplate|undefined:undefined)
const disabled=computed(()=>props.editor.readOnly.value||importing.value)
function mutate(change:()=>void){props.editor.mutate(project=>{project.schemaVersion=Math.max(3,project.schemaVersion) as 3|4;change()})}
function addBackend(provider?:{id:string;name:string;version:string;configSchema?:Record<string,any>}){const item:BackendConfig={id:newId('backend'),name:provider?.name??'新后端',providerId:provider?.id??'',providerVersion:provider?.version??'1.0.0',mode:'simulation',config:schemaDefaults(provider?.configSchema)};mutate(()=>{props.editor.project.value.backends??=[];props.editor.project.value.backends.push(item)});selected.value=item.id}
function addWindow(){const item:WindowTemplate={id:newId('window'),pageId:props.editor.project.value.pages[0]?.id??'',title:'设备设置',width:900,height:650,minWidth:640,minHeight:480,instanceKey:'deviceKey'};mutate(()=>{props.editor.project.value.windows??=[];props.editor.project.value.windows.push(item)});selected.value=item.id}
function update(key:string,value:unknown){if(!current.value)return;mutate(()=>{(current.value as any)[key]=value})}
function remove(){if(!current.value)return;const id=current.value.id;mutate(()=>{if(props.mode==='backends')props.editor.project.value.backends=backends.value.filter(item=>item.id!==id);else props.editor.project.value.windows=windows.value.filter(item=>item.id!==id)});selected.value=''}
async function importBackend(){if(disabled.value||!desktop)return;try{const path=await pickFile('directory');if(!path)return;importing.value=true;const manifest=await call<{id:string;name:string;version:string;configSchema?:Record<string,any>}>('import_backend',{path});addBackend(manifest)}catch(error){emit('error',String(error))}finally{importing.value=false}}
const dataFiles=computed(()=>(props.editor.project.value.assets??[]).filter(asset=>/\.(bin|hex|ihx|ptbcfg|json)$/i.test(asset.path)))
async function importProjectFile(){
  if(disabled.value||!desktop)return
  try{const path=await pickFile('plugin');if(!path)return;importing.value=true
    const asset=await call<{id:string;path:string;name?:string;size?:number;sha256?:string}>('import_asset',{path})
    mutate(()=>{props.editor.project.value.assets??=[];if(!props.editor.project.value.assets.some(item=>item.id===asset.id))props.editor.project.value.assets.push({id:asset.id,path:asset.path})})
  }catch(error){emit('error',String(error))}finally{importing.value=false}
}
</script>
<template><div class="backend-resources"><aside><div class="backend-resource-toolbar"><button type="button" :disabled="disabled" @click="mode==='backends'?addBackend():addWindow()">+ {{t('添加')}}</button><button v-if="mode==='backends'" type="button" :disabled="disabled||!desktop" @click="importBackend">{{t('导入后端')}}</button></div><button v-for="item in items" :key="item.id" type="button" class="backend-resource-item" :class="{active:current?.id===item.id}" @click="selected=item.id"><strong>{{'name' in item?item.name:item.title}}</strong><small>{{item.id}}</small></button><section v-if="mode==='backends'" class="backend-data-files"><button type="button" :disabled="disabled||!desktop" @click="importProjectFile">{{t('导入工程文件')}}</button><small>{{t('工程文件随运行包分发')}}</small><div v-for="asset in dataFiles" :key="asset.id" class="backend-data-file"><span :title="asset.path">{{asset.path.split(/[\\/]/).at(-1)}}</span><code>{{asset.id}}</code></div></section></aside><fieldset v-if="current" :disabled="disabled" class="backend-resource-form"><div class="backend-resource-header"><code>{{current.id}}</code><button type="button" @click="remove">{{t('删除')}}</button></div><template v-if="backend"><label>{{t('名称')}}<input :value="backend.name" @change="update('name',($event.target as HTMLInputElement).value)"></label><label>{{t('后端提供者')}}<input :value="backend.providerId" placeholder="provider.id" @change="update('providerId',($event.target as HTMLInputElement).value)"></label><label>{{t('版本')}}<input :value="backend.providerVersion" @change="update('providerVersion',($event.target as HTMLInputElement).value)"></label><label>{{t('运行模式')}}<select :value="backend.mode" @change="update('mode',($event.target as HTMLSelectElement).value)"><option value="simulation">{{t('模拟设备')}}</option><option value="usb">USB</option></select></label><label class="wide">{{t('后端配置')}}<JsonValueEditor :model-value="backend.config" type="object" :disabled="disabled" @update:model-value="update('config',$event)"/></label></template><template v-if="windowTemplate"><label>{{t('标题')}}<input :value="windowTemplate.title" @change="update('title',($event.target as HTMLInputElement).value)"></label><label>{{t('页面')}}<select :value="windowTemplate.pageId" @change="update('pageId',($event.target as HTMLSelectElement).value)"><option v-for="page in editor.project.value.pages" :key="page.id" :value="page.id">{{page.name}}</option></select></label><label v-for="field in [{key:'width',label:'宽度'},{key:'height',label:'高度'},{key:'minWidth',label:'最小宽度'},{key:'minHeight',label:'最小高度'}]" :key="field.key">{{t(field.label)}}<input type="number" min="1" :value="(windowTemplate as any)[field.key]" @change="update(field.key,Math.max(1,Number(($event.target as HTMLInputElement).value)))"></label><label class="wide">{{t('实例上下文字段')}}<input :value="windowTemplate.instanceKey" placeholder="deviceKey" @change="update('instanceKey',($event.target as HTMLInputElement).value)"></label></template></fieldset><div v-else class="backend-resource-empty">{{t(mode==='backends'?'添加或导入后端实例':'添加窗口模板并选择页面')}}</div></div></template>
<style scoped>.backend-data-files{border-top:1px solid var(--line);margin-top:8px;padding-top:6px;display:flex;flex-direction:column;gap:6px}.backend-data-files>small{font-size:10px;color:#8190a0}.backend-data-file{display:flex;flex-direction:column;font-size:11px;gap:3px;overflow-wrap:anywhere}.backend-data-file code{font-size:10px;color:#68768a;user-select:text}.backend-resources{display:flex;min-width:0;min-height:0;flex:1;overflow:hidden}.backend-resources aside{width:210px;flex-shrink:0;overflow:auto;border-right:1px solid var(--line);padding:8px;box-sizing:border-box}.backend-resource-toolbar{display:flex;justify-content:space-between;gap:8px;margin-bottom:5px}.backend-resources button{font:inherit;color:#0f6cbd;border:0;background:transparent;padding:4px;cursor:pointer}.backend-resources button:disabled{opacity:.4}.backend-resource-item{width:100%;display:flex;flex-direction:column;gap:3px;text-align:left}.backend-resource-item.active{background:#eaf3fc}.backend-resource-item small{color:#8190a0;overflow-wrap:anywhere}.backend-resource-form{border:0;margin:0;min-width:0;flex:1;overflow:auto;padding:8px 14px;display:grid;grid-template-columns:repeat(2,minmax(140px,1fr));gap:8px 12px;align-content:start}.backend-resource-header{grid-column:1/-1;display:flex;justify-content:space-between;align-items:center}.backend-resource-form label{display:flex;flex-direction:column;gap:4px;font-size:11px}.backend-resource-form .wide{grid-column:1/-1}.backend-resource-form input,.backend-resource-form select{width:100%;min-width:0;box-sizing:border-box;height:28px}.backend-resource-empty{padding:20px;color:#8190a0}@media(max-width:700px){.backend-resources aside{width:160px}.backend-resource-form{grid-template-columns:minmax(140px,1fr)}}</style>
